        (N''000000000000001888'', N''100316852'', N''indyk'', N''w wodzie do picia'', N''Zakażenia bakteryjne wrażliwe na amoksycylinę'', N''15–20 mg amoksycyliny trójwodnej/kg m.c. na dobę przez 3 dni, w ciężkich przypadkach 5 dni.'', N''data/ChPL/RPL/RPL_31685_Suramox_RPL_ChPL.pdf'', N''Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 5 dni, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 5 dni, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''niedopuszczony''),
        (N''000000000000001866'', N''100316852'', N''kura'', N''w wodzie do picia'', N''Zakażenia bakteryjne wrażliwe na amoksycylinę'', N''15 mg amoksycyliny trójwodnej/kg m.c. na dobę przez 3 dni, w ciężkich przypadkach 5 dni.'', N''data/ChPL/RPL/RPL_31685_Suramox_RPL_ChPL.pdf'', N''Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 1 dzień, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 1 dzień, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''niedopuszczony''),
        (N''000000000000001866'', N''100316852'', N''kaczka'', N''w wodzie do picia'', N''Zakażenia bakteryjne wrażliwe na amoksycylinę'', N''20 mg amoksycyliny trójwodnej/kg m.c. na dobę przez 3 dni.'', N''data/ChPL/RPL/RPL_31685_Suramox_RPL_ChPL.pdf'', N''Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 9 dni, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 9 dni, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''niedopuszczony''),
        (N''000000000000001866'', N''100316852'', N''indyk'', N''w wodzie do picia'', N''Zakażenia bakteryjne wrażliwe na amoksycylinę'', N''15–20 mg amoksycyliny trójwodnej/kg m.c. na dobę przez 3 dni, w ciężkich przypadkach 5 dni.'', N''data/ChPL/RPL/RPL_31685_Suramox_RPL_ChPL.pdf'', N''Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 5 dni, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''tk. 5 dni, Nie stosować u niosek produkujących jaja do spożycia przez ludzi ani w ciągu 3 tygodni przed nieśnością.'', N''niedopuszczony'')
    ) AS entries(symbol,rpl_id,species,route,indication,dose,pdf_path,restrictions,withdrawal_short,price,eggs)
), matched AS (
    SELECT v.id, MIN(c.eggs) AS eggs
    FROM dbo.catalog_variants v
    JOIN dbo.catalog_products p ON p.symbol = v.symbol
    LEFT JOIN dbo.catalog_price_withdrawal w ON w.id = v.id
    JOIN candidates c ON c.symbol = v.symbol AND c.rpl_id = COALESCE(v.rpl_id,N'''')
        AND c.species = v.species AND c.route = COALESCE(v.route,N'''')
        AND c.indication = COALESCE(v.indication,N'''') AND c.dose = COALESCE(v.dose,N'''')
        AND c.pdf_path = v.pdf_path AND c.restrictions = COALESCE(v.restrictions,N'''')
        AND c.withdrawal_short = COALESCE(v.withdrawal_short,N'''')
        AND c.price = COALESCE(w.compact_text,N'''')
    WHERE COALESCE(p.decision,N'''') <> N''NOT_MEDICINE''
    GROUP BY v.id HAVING MIN(c.eggs) = MAX(c.eggs)
)
UPDATE v SET eggs = m.eggs
FROM dbo.catalog_variants v JOIN matched m ON m.id = v.id
WHERE NULLIF(LTRIM(RTRIM(v.eggs)),N'''') IS NULL;

SELECT @@ROWCOUNT AS updated_variants;

-- Candidates for review against ChPL. This query does not set any values.
SELECT v.id, v.symbol, p.name, v.species, v.route, v.restrictions,
       v.withdrawal_short, w.compact_text, v.pdf_path
FROM dbo.catalog_variants v
JOIN dbo.catalog_products p ON p.symbol = v.symbol
LEFT JOIN dbo.catalog_price_withdrawal w ON w.id = v.id
WHERE NULLIF(LTRIM(RTRIM(v.eggs)), N'''') IS NULL
  AND (LOWER(v.species) LIKE N''kur%'' OR LOWER(v.species) LIKE N''%drób%''
    OR LOWER(v.species) LIKE N''indyk%'' OR LOWER(v.species) LIKE N''kaczk%''
    OR LOWER(v.species) LIKE N''gęs%'' OR LOWER(v.species) LIKE N''przepiór%''
    OR LOWER(v.restrictions) LIKE N''%jaj%'' OR LOWER(v.withdrawal_short) LIKE N''%jaj%''
    OR LOWER(w.compact_text) LIKE N''%jaj%'')
ORDER BY p.name, v.id;';
COMMIT TRANSACTION;
